import { escapeHtml as e } from './operations-page.ts';
import { stepNames } from './direct.ts';
import { renderPhrasePreparation } from './search-phrases-page.ts';
import type { DirectView } from './direct.ts';
import type { CampaignView } from './campaign.ts';
import { hasUnresolvedDirect } from './direct-pending.ts';
const hidden = (key: string, value: string | number) => `<input type="hidden" name="${key}" value="${e(String(value))}">`;
const confirm = (text: string) => `<label class="check"><input type="checkbox" name="confirm" value="yes" required>${text}</label>`;
const time = (value: string) => new Date(value).toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' }) + ' МСК';
const phases = { ready: 'Подготовлено', pending: 'Результат неизвестен · нужна сверка', confirmed: 'Подтверждено API', conflict: 'Конфликт · запись не выполнена', rejected: 'Запрос отклонён · запись не подтверждена' };
export function renderDirect(view: DirectView | undefined, campaign: CampaignView, history = false, prepared = false, currentPlanId?: string, historyEntry = false) {
  if (!view) return '';
  if (!view.enabled && !view.state && !history) return view.ownChief ? '<section class="direct-panel" id="direct"><h2>Директ</h2><p>Подготовку можно сохранить. Для создания подключите свой кабинет.</p><a href="/connections/direct">Подключить свой Директ</a></section>' : '';
  if (history && view.runs && view.runs.length > 1) return `<section id="direct-history"><h2>Директ — все сохранённые наборы</h2>${[...view.runs].reverse().map(run => renderDirect({...view,state:run,runs:undefined},campaign,true,false,undefined,true)).join('')}</section>`;
  const s = view.state;
  const canWrite=view.enabled && (!view.account || !s || view.account===s.account);
  const historyId=historyEntry?`direct-history-${s!.planId}`:'direct-history';
  const form = (action: string, content: string) => `<form method="post" action="/direct/${action}">${hidden('planId', s!.planId)}${view.ownChief?hidden('storageRevision',s!.storageRevision??0):''}${content}</form>`;
  const mode = view.mode === 'fixture' ? 'Подставной API · отдельная проверочная база' : view.ownChief ? 'Настоящий API · собственный кабинет' : 'Настоящий API · локальный тестовый кабинет';
  if (history) return `<section class="direct-panel" aria-labelledby="${historyId}"><h2 id="${historyId}">Директ — история операций</h2><p class="source-note">${mode}</p>${!s ? '<p>Операций ещё нет.</p>' : `<p>Кабинет ${e(s.account)} · кампания ${e(s.steps.campaign.id ?? 'ещё не подтверждена')}. Создание объектов не отменяется.</p><p>Группа <code>${e(s.steps.group.id??'не подтверждена')}</code> · объявление <code>${e(s.steps.ad.id??'не подтверждено')}</code> · версия плана <code>${e(s.campaignPlanId??'прежний набор')}</code></p>${[...s.events].reverse().map(event => `<article class="direct-event"><h3>${event.kind === 'create' ? 'Создание полного черновика' : event.kind === 'undo' ? 'Отмена изменения названия' : 'Изменение названия'}</h3><p><strong>${phases[event.phase]}</strong> · ${e(time(event.at))} · ${e(event.actor)}</p><dl class="preview-meta"><div><dt>До</dt><dd>${e(event.before)}</dd></div><div><dt>После</dt><dd>${e(event.after)}</dd></div></dl><p class="hint">Операция ${e(event.id)}${event.related ? ` · отменяет ${e(event.related)}` : ''}${event.undoneBy ? ` · отменена операцией ${e(event.undoneBy)}` : ''}</p>${event.error ? event.phase === 'confirmed' && !s.error ? `<details><summary>Предыдущая ошибка · результат подтверждён</summary><p>${e(event.error)}</p></details>` : `<p class="field-error">${e(event.error)}</p>` : ''}${canWrite && !hasUnresolvedDirect(s) && event.kind === 'rename' && event.phase === 'confirmed' && !event.undoneBy ? `<details><summary>Проверить и отменить изменение</summary><p>Название вернётся с «${e(event.after)}» на «${e(event.before)}». Перед записью сервис проверит текущее название и историю. Внешняя правка остановит отмену.</p>${form('undo', hidden('id', event.id) + confirm('Подтверждаю возврат названия через API.') + '<button class="secondary" type="submit">Отменить изменение в Директе</button>')}</details>` : ''}</article>`).join('')}`}</section>`;
  const started = s && Object.values(s.steps).some(entry => entry.phase !== 'ready');
  if (prepared && !started && (!s || s.campaignPlanId !== currentPlanId)) return '<section class="direct-panel" id="direct"><h2>Директ</h2><p>Подтвердите актуальный план, затем проверьте параметры. Сохранённые прежние операции остаются в истории.</p></section>';
  const status = s?.complete ? hasUnresolvedDirect(s) ? 'Набор создан · незавершённая операция требует сверки'
    : s.error ? 'Набор создан · проверьте ошибку последней операции' : 'Создана в Директе · последнее чтение: показы выключены'
    : started ? 'Создание начато · проверьте результат шагов' : 'Проверьте перед созданием';
  return `<section class="direct-panel" id="direct" aria-labelledby="direct-heading"><h2 id="direct-heading">Черновик в Директе</h2><p class="source-note">${mode}</p>
    <p>ЕПК на поиске: одна группа, целевой автотаргетинг, подтверждённый список поисковых фраз и одно комбинаторное объявление. Сети выключены. Модерации и включения показов здесь нет.</p>
    ${!started && !prepared ? renderPhrasePreparation(view, campaign) : ''}
    ${s ? `<div class="comparison"><h3>${status}</h3>
      ${hasUnresolvedDirect(s)?'<p class="hint">Есть незавершённая операция. Сначала сверить состояние Директа; новый набор и смена кабинета пока недоступны.</p>':''}${s.error ? `<p class="field-error">${e(s.error)}</p>` : ''}
      <p>Кабинет ${e(s.account)} · начало ${e(s.startDate)}. Название содержит уникальную метку для восстановления после обрыва.</p><dl class="preview-meta"><div><dt>Название при создании</dt><dd>${e(s.name)}</dd></div><div><dt>География API</dt><dd>${e(s.regionName)} · ${e(s.regionId)}</dd></div><div><dt>${s.budget?'Бюджет за период':'Недельный бюджет · прежний вариант'}</dt><dd>${e(s.budget?.amountRub??s.weekly)} ₽${s.budget?` · ${e(s.budget.startDate)} — ${e(s.budget.endDate)}, МСК · без продления`:''}</dd></div><div><dt>Поисковые фразы</dt><dd>${(s.keywordEntries?.map(k => k.phrase) ?? [s.keyword]).map(e).join('<br>')}</dd></div><div><dt>Исключения</dt><dd>${s.negatives?.length ? s.negatives.map(e).join('<br>') : 'Не заданы'}</dd></div><div><dt>Заголовок</dt><dd>${e(s.draft.title)}</dd></div><div><dt>Текст</dt><dd>${e(s.draft.adText)}</dd></div><div><dt>Ссылка</dt><dd>${e(s.draft.url)}</dd></div></dl>
      <p class="hint">Автотаргетинг: только целевые запросы, без брендов конкурентов. ${s.budget?'Периодный бюджет передаётся в стратегию API; не является суммой счёта или гарантией расхода. Изменение местного плана не меняет этот набор.':`Общий лимит ${e(s.draft.budget)} ₽ за ${e(s.draft.period)} дней — локальные данные, в API не передаётся.`}</p>
      <ul class="direct-steps">${Object.entries(s.steps).map(([key, value]) => `<li><strong>${stepNames[key as keyof typeof stepNames]}</strong>: ${phases[value.phase]}${value.id ? ` · <code>${e(value.id)}</code>` : ''}${key === 'keyword' && s.keywordEntries ? `<ul>${s.keywordEntries.map(k => `<li>${e(k.phrase)} — ${phases[k.phase]}${k.id ? ` · <code>${e(k.id)}</code>` : ''}</li>`).join('')}</ul>` : ''}</li>`).join('')}</ul>
      ${s.snapshot?.campaign ? `<h3>Последнее чтение API · сохранённое наблюдение</h3><p>${e(time(s.checkedAt!))}${s.error ? ' · есть ошибка, успешная сверка не подтверждена' : ''}</p><dl class="preview-meta"><div><dt>Фактическое название</dt><dd>${e(s.snapshot.campaign.Name)}</dd></div><div><dt>Кампания</dt><dd>${e(s.snapshot.campaign.Status)} / ${e(s.snapshot.campaign.State)}</dd></div><div><dt>Объявление</dt><dd>${e(s.snapshot.ad?.Status ?? 'нет')} / ${e(s.snapshot.ad?.State ?? 'нет')}</dd></div><div><dt>Показы / клики</dt><dd>${e(String(s.snapshot.campaign.Statistics?.Impressions ?? 'неизвестно'))} / ${e(String(s.snapshot.campaign.Statistics?.Clicks ?? 'неизвестно'))}</dd></div></dl>` : '<p>Фактическое состояние ещё не прочитано.</p>'}
      ${canWrite ? form('refresh', '<button class="secondary" type="submit">Сверить состояние Директа</button><p class="hint">Только чтение. Неизвестная запись не отправляется повторно.</p>') : '<p><a href="/connections/direct">Подключите этот кабинет заново для сверки</a>. История сохранена; показано прежнее чтение.</p>'}
      ${canWrite && !view.needsReconcile && !s.complete ? form('create', confirm(started ? 'Подтверждаю создание только ещё не начатых шагов после сверки.' : s.budget?'Я проверил текст, ссылку, географию, сумму и даты периодного бюджета. Создать объекты в Директе без показов.':'Я проверил текст, ссылку, географию и недельный бюджет. Создать объекты в Директе без показов.') + `<button class="primary" type="submit">${started ? 'Продолжить создание после сверки' : 'Создать черновик в Директе'}</button>`) : canWrite && !view.needsReconcile && !hasUnresolvedDirect(s) && s.complete && s.snapshot?.campaign ? `<h3>Изменить название</h3>${form('rename', hidden('before', s.snapshot.campaign.Name) + `<div class="field"><label for="direct-rename">Новое название кампании</label><input id="direct-rename" name="name" maxlength="255" required value="${e(view.input?.action === 'rename' ? view.input.name : s.snapshot.campaign.Name)}"></div>` + confirm('Подтверждаю изменение названия через API.') + '<button class="secondary" type="submit">Изменить название в Директе</button>')}` : ''}
      <p><a href="/history#direct-history">История и отмена изменения названия</a></p><p class="hint">Создание всего набора объектов не отменяется. Не редактируйте и не запускайте эту кампанию параллельно в Директе. Изменения локального черновика после создания не отправляются в API.</p></div>` : ''}
  </section>`;
}
